# client_recettes.py
"""Client TheMealDB pour l'app Cuisine — projet de fin de chapitre 9."""
from __future__ import annotations

import random
import time
from dataclasses import dataclass, field

import httpx

BASE_URL = "https://www.themealdb.com/api/json/v1/1"


# ---------- Contrats ----------

class ErreurApi(Exception): ...
class ApiIndisponible(ErreurApi): ...
class RecetteApiInconnue(ErreurApi): ...
class DonneesInattendues(ErreurApi): ...


@dataclass(frozen=True)
class IngredientDose:
    nom: str
    quantite: str


@dataclass(frozen=True)
class RecetteResume:
    id: str
    nom: str
    image: str


@dataclass(frozen=True)
class RecetteDetail:
    id: str
    nom: str
    categorie: str
    zone: str
    instructions: str
    ingredients: tuple[IngredientDose, ...]     # tuple : hashable, immuable


# ---------- Normalisation (fonctions pures, testables sans réseau) ----------

def _normaliser_resume(meal: dict) -> RecetteResume:
    try:
        return RecetteResume(id=meal["idMeal"], nom=meal["strMeal"],
                             image=meal["strMealThumb"] or "")
    except KeyError as exc:
        raise DonneesInattendues(f"champ manquant : {exc}") from exc


def _normaliser_detail(meal: dict) -> RecetteDetail:
    ingredients = []
    for n in range(1, 21):
        nom = (meal.get(f"strIngredient{n}") or "").strip()
        if nom:
            ingredients.append(IngredientDose(
                nom=nom, quantite=(meal.get(f"strMeasure{n}") or "").strip()))
    try:
        return RecetteDetail(
            id=meal["idMeal"], nom=meal["strMeal"],
            categorie=meal.get("strCategory") or "",
            zone=meal.get("strArea") or "",
            instructions=meal.get("strInstructions") or "",
            ingredients=tuple(ingredients))
    except KeyError as exc:
        raise DonneesInattendues(f"champ manquant : {exc}") from exc


# ---------- Client ----------

class ClientRecettes:
    def __init__(self, base_url: str = BASE_URL, timeout: float = 10.0,
                 essais: int = 3) -> None:
        self._client = httpx.Client(base_url=base_url, timeout=timeout)
        self._essais = essais
        self._cache: dict[tuple, dict] = {}
        self.requetes_emises = 0

    # -- transport : le SEUL endroit qui parle réseau --
    def _get(self, endpoint: str, params: dict) -> dict:
        cle = (endpoint, tuple(sorted(params.items())))
        if cle in self._cache:
            return self._cache[cle]

        for essai in range(self._essais):
            try:
                reponse = self._client.get(endpoint, params=params)
                self.requetes_emises += 1
                if reponse.status_code >= 500:
                    raise httpx.HTTPStatusError("5xx", request=reponse.request,
                                                response=reponse)
                reponse.raise_for_status()
                corps = reponse.json()
                self._cache[cle] = corps
                return corps
            except httpx.HTTPStatusError as exc:
                if exc.response.status_code < 500:
                    raise DonneesInattendues(
                        f"{endpoint} → {exc.response.status_code}") from exc
                if essai == self._essais - 1:
                    raise ApiIndisponible(f"{endpoint} : 5xx persistant") from exc
            except httpx.TransportError as exc:
                if essai == self._essais - 1:
                    raise ApiIndisponible(f"{endpoint} : réseau KO") from exc
            time.sleep(2 ** essai + random.uniform(0, 0.5))
        raise ApiIndisponible(endpoint)                   # inatteignable en pratique

    # -- API publique --
    def par_ingredient(self, ingredient: str) -> list[RecetteResume]:
        meals = self._get("/filter.php", {"i": ingredient}).get("meals") or []
        return [_normaliser_resume(m) for m in meals]

    def par_nom(self, nom: str) -> list[RecetteResume]:
        meals = self._get("/search.php", {"s": nom}).get("meals") or []
        return [_normaliser_resume(m) for m in meals]

    def detail(self, id_recette: str) -> RecetteDetail:
        meals = self._get("/lookup.php", {"i": id_recette}).get("meals") or []
        if not meals:
            raise RecetteApiInconnue(id_recette)
        return _normaliser_detail(meals[0])

    # -- cycle de vie --
    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> "ClientRecettes":
        return self

    def __exit__(self, *exc) -> None:
        self.close()


if __name__ == "__main__":
    with ClientRecettes() as api:
        resultats = api.par_ingredient("chicken")
        print(f"{len(resultats)} recettes — 1re : {resultats[0].nom}")
        d = api.detail(resultats[0].id)
        print(f"{d.nom} ({d.categorie}, {d.zone}) — {len(d.ingredients)} ingrédients")
        api.detail(resultats[0].id)                     # cache : pas de requête
        print(f"requêtes émises : {api.requetes_emises}")   # 2, pas 3 ✓
```

