MEAL_FACTICE = {"idMeal": "1", "strMeal": "Test", "strMealThumb": None,
                "strIngredient1": " Oeufs ", "strMeasure1": "3",
                "strIngredient2": "", "strIngredient3": None}


def test_normalisation_ignore_les_vides():
    d = _normaliser_detail(MEAL_FACTICE)
    assert d.ingredients == (IngredientDose("Oeufs", "3"),)


def test_cache_une_seule_requete(monkeypatch):
    reponses = {"n": 0}

    def fausse_get(self, url, params=None):
        reponses["n"] += 1
        return httpx.Response(200, json={"meals": [MEAL_FACTICE]},
                              request=httpx.Request("GET", "http://t"))

    monkeypatch.setattr(httpx.Client, "get", fausse_get)
    api = ClientRecettes()
    api.detail("1"); api.detail("1")
    assert reponses["n"] == 1


def test_500_persistant_devient_api_indisponible(monkeypatch):
    def fausse_get(self, url, params=None):
        return httpx.Response(500, request=httpx.Request("GET", "http://t"))

    monkeypatch.setattr(httpx.Client, "get", fausse_get)
    monkeypatch.setattr(time, "sleep", lambda s: None)      # pas d'attente en test
    with pytest.raises(ApiIndisponible):
        ClientRecettes(essais=2).par_nom("x")
